-- 2026-10-haven-bank.sql — Aidi Haven LLC bank transactions, Chase …5526 and Baselane …3512, Mar 2025 – Aug 2026
-- (496 rows from the month-on-month workbook; every statement ties out to the cent). Loaded into the existing
-- "Chase + Baselane" account: each calendar month's statement gets its transactions (2025 months are added; the 2026
-- monthly totals already there are kept, with gross money in/out). Operating outflows are logged as rental expenses
-- (shared across both properties, linked to the bank row); internal transfers are marked "not a rental cost".
-- Safe to run more than once: a month that already has transactions is skipped.
BEGIN;
SELECT e.organization_id, c.code, c.label, c.hint, c.sort FROM (SELECT organization_id FROM core.entities WHERE name ILIKE 'Aidi Haven%' ORDER BY created_at LIMIT 1) e,
  (VALUES ('landscaping', 'Gardening & landscaping', 'Gardener, yard work', 7), ('software', 'Software, listings & subscriptions', 'Pricing tools, listing and screening fees, apps', 8),
          ('office', 'Office, admin & bank fees', 'Virtual office, printing, postage, bank fees, meals', 9), ('travel', 'Travel & transport', 'Trips to the properties, rides', 10),
          ('other', 'Other', 'Zelle and transfers not yet itemised', 11)) AS c(code, label, hint, sort)
ON CONFLICT DO NOTHING;
CREATE TEMP TABLE hb (m text, d date, bank text, dsc text, cat text, amt numeric(18,2), ord int) ON COMMIT DROP;

DO $hb$
DECLARE org uuid; ent uuid; acc uuid; mo text; st uuid; opening numeric := 0; inn numeric; outt numeric; n int; me date; ms date;
BEGIN
  SELECT organization_id, id INTO org, ent FROM core.entities WHERE name ILIKE 'Aidi Haven%' ORDER BY created_at LIMIT 1;
  IF org IS NULL THEN RAISE NOTICE 'No Aidi Haven entity; nothing loaded.'; RETURN; END IF;
  PERFORM set_config('app.org_id', org::text, true);
  SELECT id INTO acc FROM banking.accounts WHERE organization_id = org AND entity_id = ent AND bank_name = 'Chase + Baselane' ORDER BY created_at LIMIT 1;
  IF acc IS NULL THEN INSERT INTO banking.accounts (organization_id, entity_id, bank_name, account_name, currency, kind) VALUES (org, ent, 'Chase + Baselane', 'Combined: Chase ...5526 + Baselane ...3512', 'USD', 'current') RETURNING id INTO acc; END IF;
  FOR mo IN SELECT DISTINCT hb.m FROM hb ORDER BY 1 LOOP
    ms := (mo || '-01')::date; me := (ms + interval '1 month' - interval '1 day')::date;
    SELECT coalesce(sum(amt) FILTER (WHERE amt > 0), 0), coalesce(-sum(amt) FILTER (WHERE amt < 0), 0), count(*) INTO inn, outt, n FROM hb WHERE hb.m = mo;
    SELECT id INTO st FROM banking.statements WHERE account_id = acc AND period_start = ms AND period_end = me;
    IF st IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM banking.transactions WHERE statement_id = st) THEN
        SELECT closing_balance INTO opening FROM banking.statements WHERE id = st; CONTINUE;
      END IF;
      IF abs((SELECT closing_balance FROM banking.statements WHERE id = st) - (opening + inn - outt)) > 0.01 THEN
        RAISE NOTICE 'Skipped %: the closing balance on file differs from the transactions.', mo;
        SELECT closing_balance INTO opening FROM banking.statements WHERE id = st; CONTINUE;
      END IF;
      UPDATE banking.statements SET opening_balance = opening, credits_total = inn, debits_total = outt, txn_count = n WHERE id = st;
    ELSE
      VALUES (org, acc, ms, me, opening, opening + inn - outt, inn, outt, n, true, 'manual') RETURNING id INTO st;
    END IF;
      SELECT org, st, acc, d, dsc, amt FROM hb WHERE hb.m = mo ORDER BY ord;
    opening := opening + inn - outt;
  END LOOP;
  -- Rental expenses from operating outflows (shared across properties), and internal transfers marked not a rental cost.
    SELECT DISTINCT ON (t.id) org, NULL::uuid, c.code, left(regexp_replace(t.description, '^\[[A-Za-z]+\] ', ''), 300), split_part(t.description, ']', 1) || ']', -t.amount, t.txn_date, 'From the bank workbook · ' || hb.cat, t.id
      FROM banking.transactions t JOIN hb ON hb.d = t.txn_date AND hb.amt = t.amount AND hb.dsc = t.description
      JOIN (VALUES ('Rent','rent_fees'), ('Cleaning','cleaning'), ('Supplies & Furnishings','supplies'), ('Zelle Payments – Other','other'), ('Software & Subscriptions','software'), ('Travel & Transport','travel'), ('International Transfers (Lemfi)','other'), ('Other','other'), ('Gardening & Landscaping','landscaping'), ('Utilities & Telecom','utilities'), ('Licenses, Taxes & Registration','rent_fees'), ('Listings & Tenant Screening','software'), ('Insurance','rent_fees'), ('Meals & Entertainment','office'), ('Bank Fees','office'), ('Office & Virtual Office','office'), ('Printing & Shipping','office')) AS c(cat, code) ON c.cat = hb.cat
     WHERE t.account_id = acc AND t.amount < 0 AND NOT EXISTS (SELECT 1 FROM rentals.expenses e WHERE e.bank_txn_id = t.id);
    SELECT DISTINCT org, t.id FROM banking.transactions t JOIN hb ON hb.d = t.txn_date AND hb.amt = t.amount AND hb.dsc = t.description
     WHERE t.account_id = acc AND t.amount < 0 AND hb.cat IN ('Transfer – Chase ↔ Baselane', 'Internal Transfer Out') ON CONFLICT DO NOTHING;
END $hb$;
COMMIT;
